export function sheetGeom(slug: string): SheetGeom | undefined {
  return GEOM[slug];
}

export function sheetFill(slug: string, row: number, visColIdx: number): string | undefined {
  const g = GEOM[slug];
  const line = g?.rows[row];
  if (!g || !line) return undefined;
  const idx = ALPHABET.indexOf(line[visColIdx] ?? "0");
  return idx > 0 ? g.p[idx] : undefined;
}
